<script lang="ts">
  import { bag } from '../../stores/bag.svelte.ts';
  import { showGameTooltip, hideGameTooltip } from '../../ui/scheduleTooltipHelpers.ts';

  let sections = $derived(bag.eggSections);

  function showSlotTooltip(e: MouseEvent | FocusEvent, locked: boolean, tooltip: string, lockLabel: string): void {
    const body = locked ? lockLabel : tooltip;
    if (!body) return;
    showGameTooltip(e, '', body);
  }
</script>

<div
  class="incubators-container"
  id="incubatorsContainer"
  data-svelte-ui="1"
  data-slot-count={String(sections.displayedSlotCount)}
>
  {#each sections.incubators as slot (slot.index)}
    <div
      class="incubator-slot rarity-{slot.rarity}{slot.ready ? ' incubator-ready' : ''}{slot.locked ? ' incubator-locked' : ''}"
      class:incubator-locked={slot.locked}
      role="group"
      data-slot={String(slot.index)}
      data-has-egg={slot.hasEgg ? 'true' : 'false'}
      aria-label={slot.locked ? slot.lockLabel : slot.tooltip}
      onmouseenter={(e) => showSlotTooltip(e, slot.locked, slot.tooltip, slot.lockLabel)}
      onmouseleave={hideGameTooltip}
      onfocus={(e) => showSlotTooltip(e, slot.locked, slot.tooltip, slot.lockLabel)}
      onblur={hideGameTooltip}
    >
      {#if slot.locked}
        <div class="incubator-slot-inner" style="display:block;">
          <span class="incubator-lock-label">{slot.lockLabel}</span>
        </div>
      {:else}
        <div class="incubator-content" style="display:block;">
          <div class="incubator-capsule rarity-{slot.rarity}">
            <div class="incubator-body">
              <div class="incubator-progress-wrap" style="--progress: {slot.progress};">
                <div class="incubator-ring"></div>
                <div class="incubator-egg-center">
                  {#if slot.hasEgg}
                    <img
                      src="img/{slot.rarity}-egg.png"
                      class="egg-sprite incubator-egg-breath {slot.filterClass}"
                      alt=""
                    />
                  {/if}
                </div>
              </div>
            </div>
            <div class="incubator-footer">
              <span class="incubator-timer">{slot.timerText}</span>
            </div>
          </div>
        </div>
        <div
          class="incubator-auto-controls{slot.autoUnlocked ? '' : ' incubator-auto-controls-locked'}"
          style="display:flex;"
        >
          <button
            type="button"
            class="incubator-auto-toggle {slot.autoEnabled ? 'incubator-auto-on' : 'incubator-auto-off'}"
            data-slot={String(slot.index)}
            disabled={!slot.autoUnlocked}
          >{slot.autoBtnLabel}</button>
          <button
            type="button"
            class="incubator-priority-chip {slot.priorityClass}"
            data-slot={String(slot.index)}
            disabled={!slot.autoUnlocked}
          >{slot.priorityLabel}</button>
        </div>
      {/if}
    </div>
  {/each}
</div>
