<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- item badges/icons from bagSnapshot */
  import type { BagItemCardSnapshot } from '../../bus/snapshots.js';
  import { buildEvolutionItemBagTooltipDescription } from '../../lib/evolutionItemTooltip.ts';
  import { game } from '../../../gameManager.js';

  let { card }: { card: BagItemCardSnapshot } = $props();

  const actionAttrs = $derived(
    card.action === 'useItem'
      ? { 'data-action': 'useItem', 'data-arg': card.itemKey, 'data-arg2': '1' }
      : card.action === 'toastBagItemHint'
        ? { 'data-action': 'toastBagItemHint', 'data-arg': card.itemKey }
        : { 'data-action': card.action },
  );

  function onMouseEnter(e: MouseEvent): void {
    const desc = card.action === 'toastEvolutionItem' && game
      ? buildEvolutionItemBagTooltipDescription(game, card.itemKey, card.description)
      : card.description;
    game?.scheduleTooltip?.(e, card.displayName, desc);
  }

  function onMouseLeave(): void {
    game?.hideTooltip?.();
  }
</script>

<div class="inventory-slot rarity-{card.rarity}{card.extraClass}">
  <div
    class="inventory-slot-content"
    style="width:100%; display:flex; flex-direction:column; align-items:center; justify-content:flex-start; gap:4px;"
    {...actionAttrs}
    onmouseenter={onMouseEnter}
    onmouseleave={onMouseLeave}
  >
    {#if card.typeBadgeHtml}
      <!-- svelte-ignore a11y_no_static_element_interactions -->
      {@html card.typeBadgeHtml}
    {/if}
    <div class="item-icon">
      <!-- svelte-ignore a11y_no_static_element_interactions -->
      {@html card.iconHtml}
    </div>
    <div class="item-count">x{card.count}</div>
    <div class="item-name">{card.displayName}</div>
    {#if card.ctrlAllHint}
      <div style="font-size: 9px; color: #94a3b8; margin-top: 2px; opacity: 1; min-height:11px;">
        {card.ctrlAllHint}
      </div>
    {/if}
  </div>
</div>
