<script lang="ts">
  import BagItemsGrid from './bag/BagItemsGrid.svelte';
  import BagIncubatorsGrid from './bag/BagIncubatorsGrid.svelte';
  import BagEggsInventory from './bag/BagEggsInventory.svelte';
  import { bag } from '../stores/bag.svelte.js';
  import { showGameTooltip, hideGameTooltip } from '../ui/scheduleTooltipHelpers.ts';

  let ui = $derived(bag.ui);
  let autoCatch = $derived(bag.autoCatch);
  let eggMeta = $derived(bag.eggMeta);

  function showTooltip(e: MouseEvent | FocusEvent, text: string): void {
    if (!text) return;
    showGameTooltip(e, '', text);
  }

  function showIncubatorBoostTooltip(e: MouseEvent | FocusEvent): void {
    if (!eggMeta.incubatorBoostTitle) return;
    showGameTooltip(e, '', eggMeta.incubatorBoostTitle.replace(/\n/g, '<br>'));
  }

  function showHelpTooltip(e: MouseEvent | FocusEvent): void {
    showTooltip(e, ui.autoCatchHelp);
  }

  function showMasterNormalTooltip(e: MouseEvent | FocusEvent): void {
    showTooltip(e, ui.autoCatchMasterTooltipNormal);
  }

  function showMasterShinyTooltip(e: MouseEvent | FocusEvent): void {
    showTooltip(e, ui.autoCatchMasterTooltipShiny);
  }

  function showMasterRoamerTooltip(e: MouseEvent | FocusEvent): void {
    showTooltip(e, ui.autoCatchMasterTooltipRoamer);
  }

  function showMasterLegendaryTooltip(e: MouseEvent | FocusEvent): void {
    showTooltip(e, ui.autoCatchMasterTooltipLegendary);
  }

  function hideHelpTooltip(): void {
    hideGameTooltip();
  }
</script>

<div id="autoCatcherPanel" class="porygon-panel" style:display={autoCatch.panelVisible ? 'block' : 'none'}>
  <div class="porygon-header">
    <div class="porygon-header-inner">
      <div>
        <div id="bagPorygonTitleLabel" class="porygon-title">{ui.porygonTitle}</div>
        <div id="bagPorygonDescLabel" class="porygon-desc">{ui.porygonDesc}</div>
      </div>
    </div>
  </div>
  <div class="auto-catch-toggles">
    <div class="auto-catch-toggle-row">
      <span id="bagAutoCatchActiveLabel" class="auto-catch-row-label">{ui.autoCatchActive}</span>
      <div class="auto-catch-toggle-row-actions">
        {#if autoCatch.showMasterballSetting}
          <button
            type="button"
            id="ac-master-active"
            class="auto-catch-master-sprite-btn"
            class:is-on={autoCatch.useMasterballActiveTargets}
            class:is-off={!autoCatch.useMasterballActiveTargets}
            aria-pressed={autoCatch.useMasterballActiveTargets ? 'true' : 'false'}
            aria-label={ui.autoCatchMasterTooltipNormal}
            data-action="toggleAutoCatch"
            data-arg="masterActive"
            onmouseenter={showMasterNormalTooltip}
            onmouseleave={hideHelpTooltip}
            onfocus={showMasterNormalTooltip}
            onblur={hideHelpTooltip}
          >
            <img src={ui.masterBallImg} alt="" />
          </button>
        {/if}
        <button
          type="button"
          id="ac-enabled"
          class="auto-catch-toggle-btn"
          class:is-on={autoCatch.enabled}
          class:is-off={!autoCatch.enabled}
          aria-pressed={autoCatch.enabled ? 'true' : 'false'}
          data-action="toggleAutoCatch"
          data-arg="enabled"
        >{autoCatch.enabled ? ui.toggleOn : ui.toggleOff}</button>
      </div>
    </div>
    <div class="auto-catch-toggle-row">
      <span id="bagAutoCatchShinyLabel" class="auto-catch-row-label">{ui.autoCatchShiny}</span>
      <div class="auto-catch-toggle-row-actions">
        {#if autoCatch.showMasterballSetting}
          <button
            type="button"
            id="ac-master-shiny"
            class="auto-catch-master-sprite-btn"
            class:is-on={autoCatch.useMasterballShiny}
            class:is-off={!autoCatch.useMasterballShiny}
            aria-pressed={autoCatch.useMasterballShiny ? 'true' : 'false'}
            aria-label={ui.autoCatchMasterTooltipShiny}
            data-action="toggleAutoCatch"
            data-arg="masterShiny"
            onmouseenter={showMasterShinyTooltip}
            onmouseleave={hideHelpTooltip}
            onfocus={showMasterShinyTooltip}
            onblur={hideHelpTooltip}
          >
            <img src={ui.masterBallImg} alt="" />
          </button>
        {/if}
        <button
          type="button"
          id="ac-shiny"
          class="auto-catch-toggle-btn"
          class:is-on={autoCatch.catchShiny}
          class:is-off={!autoCatch.catchShiny}
          aria-pressed={autoCatch.catchShiny ? 'true' : 'false'}
          data-action="toggleAutoCatch"
          data-arg="shiny"
        >{autoCatch.catchShiny ? ui.toggleOn : ui.toggleOff}</button>
      </div>
    </div>
    <div class="auto-catch-toggle-row">
      <span id="bagAutoCatchRoamerLabel" class="auto-catch-row-label">{ui.autoCatchRoamer}</span>
      <div class="auto-catch-toggle-row-actions">
        {#if autoCatch.showMasterballSetting}
          <button
            type="button"
            id="ac-master-roamer"
            class="auto-catch-master-sprite-btn"
            class:is-on={autoCatch.useMasterballRoamer}
            class:is-off={!autoCatch.useMasterballRoamer}
            aria-pressed={autoCatch.useMasterballRoamer ? 'true' : 'false'}
            aria-label={ui.autoCatchMasterTooltipRoamer}
            data-action="toggleAutoCatch"
            data-arg="masterRoamer"
            onmouseenter={showMasterRoamerTooltip}
            onmouseleave={hideHelpTooltip}
            onfocus={showMasterRoamerTooltip}
            onblur={hideHelpTooltip}
          >
            <img src={ui.masterBallImg} alt="" />
          </button>
        {/if}
        <button
          type="button"
          id="ac-roamer"
          class="auto-catch-toggle-btn"
          class:is-on={autoCatch.catchRoamer}
          class:is-off={!autoCatch.catchRoamer}
          aria-pressed={autoCatch.catchRoamer ? 'true' : 'false'}
          data-action="toggleAutoCatch"
          data-arg="roamer"
        >{autoCatch.catchRoamer ? ui.toggleOn : ui.toggleOff}</button>
      </div>
    </div>
    <div class="auto-catch-toggle-row">
      <span id="bagAutoCatchLegendaryLabel" class="auto-catch-row-label">{ui.autoCatchLegendary}</span>
      <div class="auto-catch-toggle-row-actions">
        {#if autoCatch.showMasterballSetting}
          <button
            type="button"
            id="ac-master-legendary"
            class="auto-catch-master-sprite-btn"
            class:is-on={autoCatch.useMasterballLegendary}
            class:is-off={!autoCatch.useMasterballLegendary}
            aria-pressed={autoCatch.useMasterballLegendary ? 'true' : 'false'}
            aria-label={ui.autoCatchMasterTooltipLegendary}
            data-action="toggleAutoCatch"
            data-arg="masterLegendary"
            onmouseenter={showMasterLegendaryTooltip}
            onmouseleave={hideHelpTooltip}
            onfocus={showMasterLegendaryTooltip}
            onblur={hideHelpTooltip}
          >
            <img src={ui.masterBallImg} alt="" />
          </button>
        {/if}
        <button
          type="button"
          id="ac-legendary"
          class="auto-catch-toggle-btn"
          class:is-on={autoCatch.catchLegendary}
          class:is-off={!autoCatch.catchLegendary}
          aria-pressed={autoCatch.catchLegendary ? 'true' : 'false'}
          data-action="toggleAutoCatch"
          data-arg="legendary"
        >{autoCatch.catchLegendary ? ui.toggleOn : ui.toggleOff}</button>
      </div>
    </div>
  </div>
  <div
    id="ac-ball-controls"
    class="auto-catch-ball-controls"
    style:display={autoCatch.showBallControls ? 'grid' : 'none'}
  >
    <div class="auto-catch-toggle-row auto-catch-control-row auto-catch-control-row--with-help">
      <button
        type="button"
        id="bagAutoCatchHelpTrigger"
        class="auto-catch-help-trigger"
        aria-label={ui.autoCatchHelp}
        onmouseenter={showHelpTooltip}
        onmouseleave={hideHelpTooltip}
        onfocus={showHelpTooltip}
        onblur={hideHelpTooltip}
      >?</button>
      <label id="bagAutoCatchMinChanceLabel" for="ac-min-chance" class="auto-catch-control-label">{ui.autoCatchMinChance}</label>
      <div class="auto-catch-threshold-field">
        <input
          type="number"
          id="ac-min-chance"
          class="auto-catch-number"
          min="0"
          max="100"
          step="1"
          value={autoCatch.minChancePct}
          data-action-on-change="setAutoCatchMinChance"
        >
        <span class="auto-catch-threshold-unit">%</span>
      </div>
    </div>
  </div>
</div>

<h3 class="incubator-title-row">
  <span id="bagIncubatorsTitleLabel">{ui.incubatorsTitle}</span>
  <span
    id="incubatorBoostInlineIndicator"
    class="incubator-boost-inline-indicator"
    role="img"
    aria-label={eggMeta.incubatorBoostTitle}
    style:display={eggMeta.incubatorBoostVisible ? 'inline-flex' : 'none'}
    onmouseenter={showIncubatorBoostTooltip}
    onmouseleave={hideHelpTooltip}
  >{eggMeta.incubatorBoostText}</span>
</h3>
<BagIncubatorsGrid />
<hr style="margin: 20px 0;">

<h3><span id="bagEggInventoryTitleLabel">{ui.eggInventoryTitle}</span> (<span id="ballCount">{bag.eggMeta.eggsTotalCount}</span>)</h3>
<BagEggsInventory />
<hr style="margin: 20px 0;">
<div id="activeStatBoosts"></div>
<BagItemsGrid />
